// OutLayer entry: JSON in on stdin, `{ success, output, error }` out on stdout. The secret `PROTECTED_BRAIN_SEED` is
// generated by OutLayer inside the TEE and reaches the module as an environment variable; it never leaves. For a plan
// the module first checks the run's signer (`NEAR_SENDER_ID`, over HTTPS the payment key's owner) against the keeper,
// then reads the factory through the worker's own RPC and asks NEAR AI Cloud over HTTPS with the project's secret
// `NEAR_AI_API_KEY`, both from inside the TEE.

#[cfg(target_os = "wasi")]
mod world {
    use maskwars_brain::mind::{Chain, Llm, Reply, Usage};
    use serde_json::{json, Value};
    use std::time::Duration;
    use wasi_http_client::Client;

    /// The NEAR RPC that the OutLayer worker itself gives the module (`near:rpc`), for the network it serves.
    pub struct WorkerRpc;

    impl Chain for WorkerRpc {
        fn rpc(&self, method: &str, params: Value) -> Result<Value, String> {
            let (body, error) = outlayer::raw::rpc::raw(method, &params.to_string());
            if !error.is_empty() {
                return Err("the worker's RPC is unreachable".into());
            }
            serde_json::from_str(&body).map_err(|_| "the RPC's answer is not JSON".to_string())
        }
    }

    /// NEAR AI Cloud's chat completions: canonical model ids, no aliasing, no streaming.
    pub struct NearAi {
        pub key: String,
    }

    impl Llm for NearAi {
        fn complete(
            &self,
            model: &str,
            messages: &[Value],
            max_tokens: u32,
            temperature: f32,
        ) -> Result<Reply, String> {
            let body = json!({ "model": model, "messages": messages, "stream": false, "max_tokens": max_tokens,
                               "temperature": temperature });
            let res = Client::new()
                .post("https://cloud-api.near.ai/v1/chat/completions")
                .header("content-type", "application/json")
                .header("accept", "application/json")
                .header("authorization", format!("Bearer {}", self.key))
                .header("x-no-aliasing", "true")
                .header("user-agent", "maskwars-brain")
                .body(body.to_string().as_bytes())
                .connect_timeout(Duration::from_secs(10))
                .send()
                .map_err(|_| "NEAR AI is unreachable".to_string())?;
            let status = res.status();
            if status != 200 {
                return Err(format!("NEAR AI answered {status}"));
            }
            let body = res
                .body()
                .map_err(|_| "NEAR AI's answer was cut".to_string())?;
            let v: Value = serde_json::from_slice(&body)
                .map_err(|_| "NEAR AI's answer is not JSON".to_string())?;
            let text = v["choices"][0]["message"]["content"]
                .as_str()
                .ok_or("NEAR AI's answer has no message")?;
            let usage = Usage {
                prompt_tokens: v["usage"]["prompt_tokens"].as_u64().unwrap_or(0),
                completion_tokens: v["usage"]["completion_tokens"].as_u64().unwrap_or(0),
                cached_tokens: v["usage"]["prompt_tokens_details"]["cached_tokens"]
                    .as_u64()
                    .unwrap_or(0),
            };
            Ok(Reply {
                text: text.to_string(),
                model: v["model"].as_str().unwrap_or_default().to_string(),
                usage,
            })
        }
    }
}

#[cfg(target_os = "wasi")]
fn main() {
    use maskwars_brain::{handle, Input, Output};
    use outlayer::env;

    let seed = std::env::var("PROTECTED_BRAIN_SEED")
        .ok()
        .filter(|s| !s.is_empty());
    let llm = world::NearAi {
        key: std::env::var("NEAR_AI_API_KEY").unwrap_or_default(),
    };
    let out = match env::input_json::<Input>() {
        Ok(Some(input)) => {
            let caller = env::signer_account_id().filter(|s| !s.is_empty());
            handle(
                input,
                seed.as_deref(),
                caller.as_deref(),
                &world::WorkerRpc,
                &llm,
            )
        }
        _ => Output {
            success: false,
            output: serde_json::Value::Null,
            error: Some("bad input".into()),
        },
    };
    let _ = env::output_json(&out);
}

#[cfg(not(target_os = "wasi"))]
fn main() {
    eprintln!("maskwars-brain runs on OutLayer: build with --target wasm32-wasip2");
    std::process::exit(1);
}
